#include "licensing/PublicKey.h"

namespace dojo::licensing
{
namespace
{
// The public key, masked so it is not a plain 32-byte run in the binary. Generated by the private
// key generator ("pubkey"); the mask changes each time it is printed.
constexpr std::uint8_t kMask[32] = {0xbb, 0x7f, 0x44, 0x7b, 0x2c, 0x7e, 0x2c, 0x30, 0x7d, 0x27, 0x6a, 0x50, 0x7d, 0x15, 0xed, 0x3d, 0xca, 0xbb, 0x68, 0x0b, 0xf0, 0x02, 0x33, 0xa2, 0xa8, 0x62, 0xef, 0x6c, 0x77, 0xab, 0x0d, 0xf6};
constexpr std::uint8_t kMasked[32] = {0x7f, 0x61, 0x0a, 0x82, 0x1b, 0x73, 0x4f, 0xbf, 0x86, 0x4c, 0x05, 0x5b, 0x44, 0xd4, 0x05, 0xf5, 0x11, 0x20, 0xe9, 0x36, 0x27, 0x97, 0xef, 0xcc, 0xe5, 0x76, 0xc0, 0xee, 0x56, 0xfb, 0xcd, 0xd0};

// A second masked copy of the same key: a patcher must change both consistently or no key validates.
constexpr std::uint8_t kMask2[32] = {0x2a, 0xec, 0xa1, 0x6c, 0x4e, 0x33, 0x33, 0xaa, 0x43, 0x14, 0x95, 0x38, 0xf9, 0xd2, 0x1d, 0x27, 0x55, 0xf4, 0x1f, 0x8e, 0xc2, 0x79, 0xca, 0x9a, 0xdb, 0x22, 0x21, 0x67, 0x4f, 0x40, 0x38, 0x9c};
constexpr std::uint8_t kMasked2[32] = {0xee, 0xf2, 0xef, 0x95, 0x79, 0x3e, 0x50, 0x25, 0xb8, 0x7f, 0xfa, 0x33, 0xc0, 0x13, 0xf5, 0xef, 0x8e, 0x6f, 0x9e, 0xb3, 0x15, 0xec, 0x16, 0xf4, 0x96, 0x36, 0x0e, 0xe5, 0x6e, 0x10, 0xf8, 0xba};

struct Revoked
{
    Tier tier;
    std::uint32_t serial;
};

// Keys taken back: { Tier::pro, 1234 }, ...
constexpr Revoked kRevoked[] = {
    {Tier::basic, 100}, // (test keys made while building the licensing; never issued)
    {Tier::pro, 101},
};
} // namespace

crypto::PublicKey getProductionPublicKey() noexcept
{
    crypto::PublicKey key{};
    std::uint8_t mismatch = 0;
    for (std::size_t i = 0; i < key.size(); ++i)
    {
        const auto a = static_cast<std::uint8_t>(kMasked[i] ^ kMask[i]);
        const auto b = static_cast<std::uint8_t>(kMasked2[i] ^ kMask2[i]);
        mismatch = static_cast<std::uint8_t>(mismatch | (a ^ b));
        key[i] = a;
    }
    // The two copies disagree (one was patched): return a key no signature can satisfy.
    if (mismatch != 0)
        key.fill(0);
    return key;
}

bool isRevoked(const Payload& payload) noexcept
{
    for (const auto& revoked : kRevoked)
        if (revoked.tier == payload.tier && revoked.serial == payload.serial)
            return true;
    return false;
}

} // namespace dojo::licensing
